mapper.select:
SELECT a.state, a.`name`, a.arch_name AS 'archName', d.`label` AS 'states', a.create_time AS 'createTime', b.id AS 'id', b.hots_id AS 'hotsId', b.channel, b.nickname, b.country, c2.name AS 'countrys', b.contact, b.avg_play_count AS 'avgPlayCount', b.score_level AS 'scoreLevel', b.`is_match` AS 'isMatch', d1.`label` AS 'isMatchs' FROM `a_hot` a JOIN `a_hot_basic` b ON b.`hot_id` = a.`id` AND b.`del_flag` = 0 LEFT JOIN `a_hot_coop` c ON c.`hotb_id` = b.`id` AND c.`del_flag` = 0 LEFT JOIN `a_hot_coop_product` c1 ON c1.`coop_id` = c.`id` AND c1.`del_flag` = 0 LEFT JOIN `sys_dict` d ON d.`value` = a.`state` AND d.`type` = 'hot_coop_state' AND d.`del_flag` = 0 LEFT JOIN `sys_dict` d1 ON d1.`value` = b.`is_match` AND d1.`type` = 'is_match' AND d1.`del_flag` = 0 LEFT JOIN `b_follower` f ON b.`follower` BETWEEN f.`s_num` AND IFNULL(f.`e_num`,b.`follower`) LEFT JOIN `a_country` c2 ON c2.`id` = b.`country` LEFT JOIN `a_hot_type` t ON t.hotb_id = b.id JOIN `sys_user_country` uc ON uc.`country_id` = b.`country` WHERE a.`del_flag` = 0 AND uc.`user_id` = #{userid}
AND b.`country` = #{country}
AND b.`hot_level` = #{hotLevel}
AND t.kol_id = #{hotType}
AND b.`channel` = #{channel}
AND b.`hots_id` LIKE CONCAT('%',#{hotsId},'%')
AND b.`is_match` = #{isMatch}
AND a.`state` = #{state}
AND c1.`product_name` LIKE CONCAT('%',#{productName},'%')
AND c1.`coop_fee` <= #{coopFee}
AND f.`id` = #{follower}
AND b.`id` IN
#{id}
GROUP BY b.`id` ORDER BY a.create_time DESC

SELECT a.id, a.doc_num AS 'docNum', a.bd_name AS 'bdName', a.conn_time AS 'connTime', a.agcc_time AS 'agccTime', a.hots_id AS 'hotsId', a.channel, a.country, c2.name AS 'countrys', a.state, d.label AS 'states', a.create_time AS 'createTime' FROM `a_hot` h JOIN `a_hot_basic` hb ON hb.hot_id = h.id AND hb.del_flag = 0 JOIN `a_hot_invit` a ON a.hotb_id = hb.id AND a.del_flag = 0 LEFT JOIN `sys_dict` d ON d.value = a.state AND d.type = 'hot_state' AND d.del_flag = 0 LEFT JOIN `a_country` c2 ON c2.`id` = a.`country` JOIN `sys_user_country` uc ON uc.`country_id` = a.`country` WHERE h.`del_flag` = 0 AND uc.`user_id` = #{userid}
AND h.id = #{id}
AND a.`create_time` >= #{sdate}
AND a.`create_time` <= #{edate}
AND a.`country` LIKE CONCAT('%',#{country},'%')
AND a.`bd_name` LIKE CONCAT('%',#{bdName},'%')
AND a.`state` = #{state}
AND a.`channel` = #{channel}
AND a.`hots_id` LIKE CONCAT('%',#{hotsId},'%')

SELECT a.id, a.doc_num AS 'docNum', a.bd_name AS 'bdName', a.hots_id AS 'hotsId', a.channel, b.product_model AS 'productModel', b.product_color AS 'productColor', a.state, d.label AS 'states', a.create_time AS 'createTime' FROM `a_hot` h JOIN `a_hot_basic` hb ON hb.hot_id = h.id AND hb.del_flag = 0 JOIN `a_hot_coop` a ON a.hotb_id = hb.id AND a.del_flag = 0 LEFT JOIN `a_hot_coop_product` b ON b.`coop_id` = a.`id` AND b.`del_flag` = 0 LEFT JOIN `sys_dict` d ON d.value = a.state AND d.type = 'hot_state' AND d.del_flag = 0 JOIN `sys_user_country` uc ON uc.`country_id` = a.`country` WHERE h.del_flag = 0 AND uc.`user_id` = #{userid}
AND h.id = #{id}
AND a.`create_time` >= #{sdate}
AND a.`create_time` <= #{edate}
AND a.`country` LIKE CONCAT('%',#{country},'%')
AND a.`bd_name` LIKE CONCAT('%',#{bdName},'%')
AND a.`state` = #{state}
AND a.`channel` = #{channel}
AND a.`hots_id` LIKE CONCAT('%',#{hotsId},'%')

SELECT b.id, b.hots_id AS 'hotsId', b.channel, b.nickname, b.country, b.contact, b.hot_level AS 'hotLevel', GROUP_CONCAT(DISTINCT k.id) AS 'hotType', GROUP_CONCAT(DISTINCT k.en_name) AS 'hotTypes', b.follower, b.juxing_url AS 'juxingUrl', b.url_link AS 'urlLink', b.avg_play_count AS 'avgPlayCount', b.avg_iact_rate AS 'avgIactRate', b.long_avg_views AS 'longAvgViews', b.long_iact_rate AS 'longIactRate', b.short_avg_views AS 'shortAvgViews', b.short_iact_rate AS 'shortIactRate', b.score_level AS 'scoreLevel' FROM `a_hot` a JOIN `a_hot_basic` b ON b.`hot_id` = a.`id` AND b.`del_flag` = 0 LEFT JOIN `a_hot_coop` c ON c.`hotb_id` = b.`id` AND c.`del_flag` = 0 LEFT JOIN `a_hot_coop_product` c1 ON c1.`coop_id` = c.`id` AND c1.`del_flag` = 0 LEFT JOIN `sys_dict` d ON d.`value` = a.`state` AND d.`type` = 'hot_coop_state' AND d.`del_flag` = 0 LEFT JOIN `sys_dict` d1 ON d1.`value` = b.`is_match` AND d1.`type` = 'is_match' AND d1.`del_flag` = 0 LEFT JOIN `b_follower` f ON b.`follower` BETWEEN f.`s_num` AND IFNULL(f.`e_num`,b.`follower`) LEFT JOIN `a_hot_type` t ON t.hotb_id = a.id LEFT JOIN `a_kol` k ON k.id = t.kol_id JOIN `sys_user_country` uc ON uc.`country_id` = b.`country` WHERE a.`del_flag` = 0 AND uc.`user_id` = #{userid}
AND b.`country` LIKE CONCAT('%',#{country},'%')
AND b.`hot_level` = #{hotLevel}
AND b.`hot_type` LIKE CONCAT('%',#{hotType},'%')
AND b.`channel` = #{channel}
AND b.`hots_id` LIKE CONCAT('%',#{hotsId},'%')
AND b.`is_match` = #{isMatch}
AND a.`state` = #{state}
AND c1.`product_name` LIKE CONCAT('%',#{productName},'%')
AND c1.`coop_fee` <= #{coopFee}
AND f.`id` = #{follower}
AND b.`id` IN
#{id}
GROUP BY b.`id` ORDER BY a.create_time DESC
